 * Cell address handling: parsing/validating "A1"-style words and converting
 * column letters to and from their 1-based numeric position (A=1 .. Z=26,
 * AA=27 .. ZZ=702).
 */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

export function colToNum(letters) {
  let n = 0
  for (const ch of letters) {
    n = n * 26 + (ch.charCodeAt(0) - 64)
  }
  return n
}

export function numToCol(n) {
  let s = ''
  while (n > 0) {
    const rem = (n - 1) % 26
    s = String.fromCharCode(65 + rem) + s
    n = Math.floor((n - 1) / 26)
  }
  return s
}

/**
 * Parses a word as a cell address. Returns null when the word is not one or
 * two letters followed by one to three digits naming a row of at least 1.
 */
export function parseAddress(word) {
  const upper = word.toUpperCase()
  const m = ADDRESS_RE.exec(upper)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  const col = colToNum(m[1])
  return { col, row, address: m[1] + String(row) }
}

export function addressString(col, row) {
  return numToCol(col) + String(row)
}

export function addressKey(col, row) {
  return col + ':' + row
}
"}

