{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-mX4DRZ/src/sheet.js","content":"/**
 * Sheet parsing: turns the raw standard-input text into an ordered map of
 * declared cells, validating addresses and rejecting duplicates.
 */

import { parseAddress, addressKey } from './address.js'

export class SheetError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/**
 * Parses sheet text into a Map from address key ("col:row") to
 * { col, row, address, content }, in declaration order.
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue

    let idx = -1
    for (let j = 0; j < stripped.length; j++) {
      const ch = stripped[j]
      if (ch === ' ' || ch === '\t') { idx = j; break }
    }

    let addressField, content
    if (idx === -1) {
      addressField = stripped
      content = ''
    } else {
      addressField = stripped.slice(0, idx)
      let rest = stripped.slice(idx)
      let j = 0
      while (j < rest.length && (rest[j] === ' ' || rest[j] === '\t')) j++
      content = rest.slice(j)
    }

    const info = parseAddress(addressField)
    if (!info) {
      throw new SheetError(lineNo, `invalid cell address ${addressField.toUpperCase()}`)
    }

    const key = addressKey(info.col, info.row)
    if (cells.has(key)) {
      throw new SheetError(lineNo, `cell ${info.address} is declared twice`)
    }

    cells.set(key, { col: info.col, row: info.row, address: info.address, content })
  }

  return cells
}
"}

