{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-mX4DRZ/src/formula.js","content":"/**
 * Formula grammar: tokenizing and recursive-descent parsing of a formula
 * body (the text following the leading "="). Anything the grammar does not
 * accept is signalled with GrammarError, which callers turn into #ERR!.
 *
 * AST node shapes:
 *   { type: 'num', value }
 *   { type: 'bool', value }
 *   { type: 'addr', word }
 *   { type: 'range', a, b }            -- only ever produced as a call argument
 *   { type: 'call', name, args }       -- args are 'range' or expression nodes
 *   { type: 'unary', op, operand }
 *   { type: 'bin', op, left, right }
 */

export class GrammarError extends Error {}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    if (c >= '0' && c <= '9') {
      let j = i + 1
      while (j < s.length && s[j] >= '0' && s[j] <= '9') j++
      if (s[j] === '.') {
        let k = j + 1
        while (k < s.length && s[k] >= '0' && s[k] <= '9') k++
        if (k > j + 1) { toks.push({ type: 'num', value: s.slice(i, k) }); i = k; continue }
      }
      toks.push({ type: 'num', value: s.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      let j = i + 1
      while (j < s.length && /[A-Za-z]/.test(s[j])) j++
      while (j < s.length && /[0-9]/.test(s[j])) j++
      toks.push({ type: 'word', value: s.slice(i, j) })
      i = j
      continue
    }
    if (c === '<') {
      if (s[i + 1] === '=') { toks.push({ type: 'op', value: '<=' }); i += 2; continue }
      if (s[i + 1] === '>') { toks.push({ type: 'op', value: '<>' }); i += 2; continue }
      toks.push({ type: 'op', value: '<' }); i++; continue
    }
    if (c === '>') {
      if (s[i + 1] === '=') { toks.push({ type: 'op', value: '>=' }); i += 2; continue }
      toks.push({ type: 'op', value: '>' }); i++; continue
    }
    if ('=^*/+-'.includes(c)) { toks.push({ type: 'op', value: c }); i++; continue }
    if (c === '(') { toks.push({ type: 'lparen' }); i++; continue }
    if (c === ')') { toks.push({ type: 'rparen' }); i++; continue }
    if (c === ',') { toks.push({ type: 'comma' }); i++; continue }
    if (c === ':') { toks.push({ type: 'colon' }); i++; continue }
    throw new GrammarError()
  }
  return toks
}

class Parser {
  constructor(tokens) {
    this.toks = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.toks[this.pos + offset]
  }

  advance() {
    return this.toks[this.pos++]
  }

  expect(type) {
    const t = this.advance()
    if (!t || t.type !== type) throw new GrammarError()
    return t
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.peek() && this.peek().type === 'op' && COMPARISON_OPS.has(this.peek().value)) {
      const op = this.advance().value
      const right = this.parseAdditive()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.peek() && this.peek().type === 'op' && (this.peek().value === '+' || this.peek().value === '-')) {
      const op = this.advance().value
      const right = this.parseMultiplicative()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.peek() && this.peek().type === 'op' && (this.peek().value === '*' || this.peek().value === '/')) {
      const op = this.advance().value
      const right = this.parsePower()
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek() && this.peek().type === 'op' && this.peek().value === '^') {
      this.advance()
      const right = this.parsePower()
      return { type: 'bin', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.peek() && this.peek().type === 'op' && (this.peek().value === '-' || this.peek().value === '+')) {
      const op = this.advance().value
      const operand = this.parseUnary()
      return { type: 'unary', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new GrammarError()
    if (t.type === 'num') {
      this.advance()
      return { type: 'num', value: parseFloat(t.value) }
    }
    if (t.type === 'lparen') {
      this.advance()
      const e = this.parseExpr()
      this.expect('rparen')
      return e
    }
    if (t.type === 'word') {
      this.advance()
      const upper = t.value.toUpperCase()
      if (this.peek() && this.peek().type === 'lparen') {
        this.advance()
        const args = this.parseArgs()
        this.expect('rparen')
        return { type: 'call', name: upper, args }
      }
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      return { type: 'addr', word: t.value }
    }
    throw new GrammarError()
  }

  parseArgs() {
    const args = []
    if (this.peek() && this.peek().type === 'rparen') return args
    for (;;) {
      args.push(this.parseArg())
      if (this.peek() && this.peek().type === 'comma') {
        this.advance()
        continue
      }
      break
    }
    return args
  }

  parseArg() {
    const t0 = this.peek(0)
    const t1 = this.peek(1)
    const t2 = this.peek(2)
    if (t0 && t0.type === 'word' && t1 && t1.type === 'colon' && t2 && t2.type === 'word') {
      const after = this.peek(3)
      if (!after || after.type === 'comma' || after.type === 'rparen') {
        this.advance()
        this.advance()
        this.advance()
        return { type: 'range', a: t0.value, b: t2.value }
      }
    }
    return this.parseExpr()
  }
}

/**
 * Parses a formula body (without the leading "="). Throws GrammarError when
 * the grammar does not accept the text.
 */
export function parseFormula(body) {
  const tokens = tokenize(body)
  const parser = new Parser(tokens)
  const ast = parser.parseExpr()
  if (parser.pos !== tokens.length) throw new GrammarError()
  return ast
}
"}

