function txt(v) { return { t: 'text', v } }
function bool(v) { return { t: 'bool', v } }
function err(v) { return { t: 'err', v } }

function parseLiteral(content) {
  if (content === '') return num(0)
  if (NUMBER_RE.test(content)) return num(parseFloat(content))
  if (ERROR_TOKENS.has(content)) return err(content)
  return txt(content)
}

