  if (v.t === 'num') return v
  if (v.t === 'bool') return num(v.v ? 1 : 0)
  if (v.t === 'text') return err('#VALUE!')
  return v
}

function finalizeNumber(n) {
  if (!Number.isFinite(n)) return err('#DIV/0!')
  return num(n)
}

function typeRank(v) {
  if (v.t === 'num') return 0
  if (v.t === 'text') return 1
  return 2
}

function compareValues(l, r, op) {
  let cmp
  if (l.t === r.t) {
    if (l.t === 'num') cmp = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
    else if (l.t === 'text') cmp = l.v < r.v ? -1 : l.v > r.v ? 1 : 0
    else cmp = (l.v ? 1 : 0) - (r.v ? 1 : 0)
  } else {
    cmp = typeRank(l) - typeRank(r)
