/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import fs from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { createEvaluator, formatValue } from './values.js'
import { collectDeps } from './deps.js'
import { numToCol } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = args[0]

  const input = fs.readFileSync(0, 'utf8')

  let cells
  try {
    cells = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(`line ${e.line}: ${e.message}`)
    throw e
  }

  const sorted = [...cells.entries()].sort((a, b) => {
    const ca = a[1], cb = b[1]
    return ca.col - cb.col || ca.row - cb.row
  })

  let out = ''
  if (mode === 'values') {
    const evaluator = createEvaluator(cells)
    for (const [key, cell] of sorted) {
      const value = evaluator.getCellValue(key)
      out += `${cell.address}=${formatValue(value)}\n`
    }
  } else {
    for (const [, cell] of sorted) {
      const depKeys = [...collectDeps(cell.content)]
      depKeys.sort((ka, kb) => {
        const [ca, ra] = ka.split(':').map(Number)
        const [cb, rb] = kb.split(':').map(Number)
        return ca - cb || ra - rb
      })
      const names = depKeys.map((k) => {
        const [c, r] = k.split(':').map(Number)
        return `${numToCol(c)}${r}`
      })
      out += `${cell.address}:${names.map((n) => ' ' + n).join('')}\n`
    }
  }

  process.stdout.write(out)
}

main()
"}

